{
  "predictors": [
    {
      "name": "Employee Growth Rate",
      "construction": "Current employee count minus employee count from one year ago, divided by employee count from one year ago.",
      "rationale": "Firms that are expanding their workforce may be experiencing growth opportunities, potentially leading to higher future earnings.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Revenue Volatility",
      "construction": "Standard deviation of quarterly revenues over the past five years.",
      "rationale": "Firms with more stable revenue streams may be perceived as less risky, thus leading to higher investor confidence and potentially higher returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Dividend Consistency",
      "construction": "Number of consecutive years with non-decreasing dividends minus number of years with dividend cuts over the past decade.",
      "rationale": "Consistent dividend policies may signal strong cash flow management and firm stability, attracting investors seeking reliable returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Launch Count",
      "construction": "Number of new products launched in the past year divided by the average number of new products launched over the past five years.",
      "rationale": "Firms increasing their product offerings might be capitalizing on innovation or market demand, potentially driving higher growth and returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Buying Intensity",
      "construction": "Total insider purchases over the past six months divided by total insider sales over the same period.",
      "rationale": "Significant insider buying relative to selling may indicate insider confidence in the firm's future prospects, which could precede price appreciation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Growth rate of patent citations over the past three years.",
      "rationale": "An increase in patent citations may suggest the firm's technologies are gaining importance, potentially leading to a competitive advantage and higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Diversification",
      "construction": "Number of unique suppliers in the most recent year divided by the number of unique suppliers three years ago.",
      "rationale": "Firms with a more diversified supplier base may reduce operational risks, which can enhance stability and return potential.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Marketing Expenditure Ratio",
      "construction": "Marketing expenses divided by total sales revenue over the past year.",
      "rationale": "A higher marketing expenditure ratio may indicate aggressive efforts to capture market share, potentially leading to future revenue growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration Risk",
      "construction": "Sales to the largest customer divided by total sales in the most recent fiscal year.",
      "rationale": "Firms with lower customer concentration may have less revenue volatility and risk, possibly leading to more stable returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Environmental Compliance Score",
      "construction": "Composite score based on the firm's adherence to environmental regulations and standards, derived from public disclosures and third-party ratings.",
      "rationale": "Firms with strong environmental compliance may mitigate regulatory risks and appeal to socially responsible investors, potentially enhancing returns.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
